void* CWorldMap::GetPGameMapCellAt(const C3DVector& pos) const
{
    if (IsPosInMap(pos))
    {
        C2DCoordI block((long)pos.X, (long)pos.Y);
        long map = GetMapNumberAt(block);
        if (map != 0 && IsMapLoaded(map))
        {
